[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [ReadiCommand]
    $Command,
    [Parameter(Mandatory)]
    [string]
    $Path
)
Do {
    $result = New-ReadiResult -Status 200
    $serviceName = $Command.Destination.ServiceName
    $nameSpace = $Command.Destination.Namespace
    $config = $Command.Destination.Config
    $archivePath = $config.ArchivePath
    try {
        $targetInfo = Get-ChildItem -Path $Path -ErrorAction Ignore
    }
    catch {
        [void] $Command.AddLogEntry([System.Net.HttpStatusCode]::InternalServerError,"Unknown error retrieving file info for ($($path)).",$_)
        $Command.IsComplete = $true
    }
    if (!$targetInfo) {
        [void] $Command.AddLogEntry([System.Net.HttpStatusCode]::InternalServerError,"File $($path) not found",$_)
        $Command.IsComplete = $true
    }
    switch ($config.OnComplete) {
        "Archive" {
            try {
                $null = Move-Item -Path $path -Destination $config.ArchivePath -Force
            }
            catch {
                [void] $Command.AddLogEntry([System.Net.HttpStatusCode]::InternalServerError,"Unknown error while attempting to archive file $($path) to $($config.ArchivePath).",$_)
                $Command.IsComplete = $true
            }
        }
        "Remove" {
            try {
                $null = Remove-Item -Path $path -Force
            }
            catch {
                [void] $Command.AddLogEntry([System.Net.HttpStatusCode]::InternalServerError,"Unknown error while attempting to archive file $($path) to $($config.ArchivePath).",$_)
                $Command.IsComplete = $true
            }
        }
    }
} Until ($Command.IsComplete)
