                                    Break
                                }
                                $fileItem = Get-ChildItem -Path $filePath -Filter $filterString -ErrorAction Ignore
                                if (!$fileItem) {
                                    $Command.Value.AddLogEntry([HttpStatusCode]::NotFound,"No file matching the pattern $($filterString) found at $($filePath). $($errorAppendString)",$null)
                                    Break
                                }
