                                    catch {
                                        {1:}
                                    }
                                }
                                if ($file.StatusCode -eq [System.Net.HttpStatusCode]::OK) {
                                    $ids = ($file.Items | Select-Object -Property ($Command.Value.Config.MemberPropertyName)).($Command.Value.Config.MemberPropertyName)
                                    try {
                                        $reconcileResult = $object.Reconcile($ids)
                                        $result.AddRange(@($reconcileResult))
                                    }
                                    catch {
                                        {1:}
                                    }
                                }
                            }
                            catch {
                                <#Do this if a terminating exception happens#>
                            }
                        }
                        "Contains object id" {

                        }
                    }
                }
                $Command.Value.IsComplete = $true
            }
        }
    } else {
        $Command.Value.AddLogEntry([HttpStatusCode]::NotFound,"No entitlement objects found in `$Command.Results.Items. Cannot sync members.",$null)
        $Command.Value.IsComplete = $true
    }
    $Command.Value.IsComplete = $true
}
return $null
