[CmdletBinding()]
param (
    [Parameter(Mandatory)]
    [ReadiCommand]
    $Command
)
while (!$Command.IsComplete) {
    $fileResult = Get-ReadiDelimitedTextFile -Path ($Command.Config.FilePaths.($Command.Class.Name)) -ConvertFrom $Command.Config.FileType -MaxDepth $Command.Config.Depth -Delimiter $Command.Config.Delimiter
    if ($fileResult.StatusCode -ne [System.Net.HttpStatusCode]::OK) {
        $Command.AddLogEntry($fileResult.Logs[0].StatusCode,$fileResult.Logs[0].StatusDescription,$fileResult.Logs[0].Message)
        $Command.Result.StatusCode = $fileResult.StatusCode
        $Command.IsComplete = $true
        break
    }
    # INSERT CODE BELOW TO PREPROCESS DATA BEFORE SUBMITTING FOR PROCESSING


    # INSERT CODE ABOVE TO PREPROCESS DATA BEFORE SUBMITTING FOR PROCESSING
    $Command.ProcessIncoming($fileResult.Items)
    if (($Command.Config.SyncMembers) -and ($Command.Options.Sync) -and (Test-ReadiClassMappedToEntitlement -Command $Command)) {
        $cmdString = "`$Global:$($Command.Destination.FQN).SyncMembers([ref]`$Command)"
        $syncMemberResult = Invoke-Expression -Command $cmdString
    }
    $Command.IsComplete = $true
}
if ($Command.Result.StatusCode -eq [HttpStatusCode]::OK) {
    $Command.Destination.Complete($Command,$Command.Config.FilePaths.($Command.Class.Name))
}
$Command.Result.Complete()
return $Command.Result
